def scan_today_signals_with_evidence(
    profile: ShadowProfile,
    *,
    target_date: str | date | None = None,
    per_market: int = 3,
    source: str = "auto",
) -> dict[str, Any]:
    """Fetch bars through the native loader and return scan plus data coverage.

    ``scan_today_signals`` remains the list-only API for existing callers. The
    native Shadow tool uses this entry point so an empty match list is paired
    with explicit source, basket, coverage, and loader-failure evidence.
    """
    if target_date is None:
        target = date.today()
    elif isinstance(target_date, date):
        target = target_date
    else:
        target = datetime.strptime(str(target_date), "%Y-%m-%d").date()

    source = str(source or "auto").strip().lower() or "auto"
    baskets: dict[str, list[str]] = {}
    for rule in profile.rules:
        market = str(rule.entry_condition.get("market", "other"))
        if market in SUPPORTED_MARKETS:
            baskets.setdefault(market, _LIQUID_BASKETS.get(market, [])[:])
    requested_symbols = list(dict.fromkeys(
        symbol for symbols in baskets.values() for symbol in symbols
    ))

    from backtest.loaders.registry import (
        get_loader_cls_with_fallback,
        resolve_loader,
    )

    loaders: dict[str, Any] = {}
    loader_errors: dict[str, tuple[str, str]] = {}
    frames: dict[str, pd.DataFrame | None] = {}
    attempted: set[str] = set()
    available: set[str] = set()
    missing: set[str] = set()
    errors: dict[str, dict[str, str]] = {}
    data_sources: dict[str, str] = {}
    coverage: dict[str, dict[str, Any]] = {}

    def fetch(symbol: str, market: str, requested_date: date) -> pd.DataFrame | None:
        attempted.add(symbol)
        if symbol in frames:
            return frames[symbol]

        market_key = _MARKET_LOADER_KEYS.get(market)
        if market_key is None:
            missing.add(symbol)
            frames[symbol] = None
            return None
        try:
            if market not in loaders and market not in loader_errors:
                if source == "auto":
                    loaders[market] = resolve_loader(market_key)
                else:
                    loaders[market] = get_loader_cls_with_fallback(source)()
            loader = loaders.get(market)
            if loader is None:
                error_type, message = loader_errors.get(
                    market, ("NoAvailableSourceError", "no loader available"),
                )
                errors[symbol] = {
                    "source": source,
                    "type": error_type,
                    "message": message[:500],
                }
                frames[symbol] = None
                return None
            data_sources[symbol] = str(getattr(loader, "name", source) or source)
            start = (requested_date - timedelta(days=90)).isoformat()
            fetched = loader.fetch(
                [symbol], start, requested_date.isoformat(), interval="1D",
            )
            frame = fetched.get(symbol)
            usable = _normalize_bars(frame, requested_date)
            if usable is None:
                missing.add(symbol)
                frames[symbol] = frame
                return frame

            available.add(symbol)
            coverage[symbol] = {
                "bar_count": len(usable),
                "first_bar": pd.Timestamp(usable.index.min()).date().isoformat(),
                "last_bar": pd.Timestamp(usable.index.max()).date().isoformat(),
            }
            frames[symbol] = frame
            return frame
        except Exception as exc:
            message = str(exc).strip() or type(exc).__name__
            loader_errors.setdefault(market, (type(exc).__name__, message))
            errors[symbol] = {
                "source": source,
                "type": type(exc).__name__,
                "message": message[:500],
            }
            frames[symbol] = None
            return None

    matches = scan_today_signals(
        profile,
        target_date=target,
        per_market=per_market,
        fetcher=fetch,
    )
    unscanned = set(requested_symbols) - attempted
    if not available:
        status = "error" if errors else "no_data"
    elif errors or missing or unscanned:
        status = "partial"
    else:
        status = "ok"
    return {
        "status": status,
        "data_status": status,
        "target_date": target.isoformat(),
        "source_requested": source,
        "baskets": baskets,
        "requested_symbols": requested_symbols,
        "scanned_symbols": sorted(attempted),
        "available_symbols": sorted(available),
        "missing_symbols": sorted(missing),
        "unscanned_symbols": sorted(unscanned),
        "data_sources": data_sources,
        "coverage": coverage,
        "errors": errors,
        "matches": matches,
    }


